        EmailEvents
        | where Timestamp > ago(30d)
    ) on NetworkMessageId
    | extend NormalizedSubject = trim_start(
        @"^([\s]*([Ff][Ww][Dd]?|[Rr][Ee]|[Ww][Gg]|[Aa][Ww]|[Tt][Rr]|[Rr][Vv]|[Ss][Vv]|[Dd][Vv])[\s]*:[\s]*)+",
