// Source: https://github.com/ge0mant1s/SOaC-Enterprise
// Collected: 2026-05-17
// KQL Library - https://github.com/sivolko/kql-library

let sensitive_patterns = dynamic([
    "BEGIN PRIVATE KEY", "AKIA", "ASIA",
    "password:", "secret_key:", "api_key:"
]);
let ai_endpoints = dynamic([
    "/v1/chat/completions", "/api/generate", "/inference"
]);
CommonSecurityLog
| where TimeGenerated > ago(1h)
| where RequestURL has_any (ai_endpoints)
| where EventOutcome == "200"
| where Message has_any (sensitive_patterns)
| extend LeakType = case(
    Message has "PRIVATE KEY", "Private Key Exposure",
    Message has "AKIA", "AWS Credential Leak",
    Message has "password:", "Credential Disclosure",
    "API Token Exposure"
)
| project TimeGenerated, SourceIP, DestinationIP, RequestURL, LeakType
| summarize LeakCount = count(), LeakTypes = make_set(LeakType),
    FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated)
    by SourceIP, RequestURL
| sort by LeakCount desc

// Source: https://github.com/sivolko/kql-library
// Collected: 2026-05-17
// KQL Library - https://github.com/sivolko/kql-library

let sql_error_patterns = dynamic([
    "you have an error in your sql syntax",
    "unclosed quotation mark after the character string",
    "syntax error at or near",
    "ora-[0-9]{5}", // Oracle error format
    "sql command not properly ended",
    "microsoft ole db provider for odbc drivers",
    "invalid column name",
    "unterminated string constant",
    "odbc driver error",
    "a syntax error has occurred"
]);

// Define the time window for the search
let lookback = 1h;

// Search across WAF and web server logs that may contain response bodies or error messages.
union isfuzzy=true AzureDiagnostics, AzureWebAppFirewallLogs, CommonSecurityLog
| where TimeGenerated > ago(lookback)
// Filter to relevant log categories.
| where (TableName == "AzureDiagnostics" and Category in ("ApplicationGatewayFirewallLog", "FrontdoorWebApplicationFirewallLog"))
    or TableName == "AzureWebAppFirewallLogs"
    or TableName == "CommonSecurityLog"
// Normalize the fields containing the response/error message into a single searchable field.
| extend SearchableResponse = tolower(case(
    TableName == "AzureDiagnostics", details_message_s,
    TableName == "AzureWebAppFirewallLogs", details_data_s,
    TableName == "CommonSecurityLog", Message,
    ""
))
// Core detection logic: Look for SQL error patterns in the response/error message.
| where SearchableResponse has_any (sql_error_patterns)
// Extract the specific error pattern that was matched for easier analysis.
| extend MatchedError = extract(strcat("(",tostring(sql_error_patterns),")"), 1, SearchableResponse)
// FP Tuning:
// - Legitimate application bugs can also expose database errors.
// - Exclude known benign error-producing endpoints or specific error messages that are common in your environment.
//   Example: | where RequestURL !has "/api/known_buggy_endpoint"
// Extract and normalize fields for investigation.
| extend
    Timestamp = TimeGenerated,
    ClientIP = case(
        isnotempty(clientIp_s), clientIp_s,
        isnotempty(clientIP_s), clientIP_s,
        isnotempty(SourceIP), SourceIP,
        ""
    ),
    RequestURL = case(
        isnotempty(requestUri_s), requestUri_s,
        isnotempty(RequestURL), RequestURL,
        ""
    ),
    HttpResponseCode = case(
        isnotempty(httpStatus_d), httpStatus_d,
        isnotempty(httpStatusCode_s), httpStatusCode_s,
        0
    ),
    RuleName = case(
        isnotempty(ruleName_s), ruleName_s,
        isnotempty(RuleName), RuleName,
        ""
    ),
    Action = case(
        isnotempty(action_s), action_s,
        isnotempty(action_s), action_s,
        isnotempty(DeviceAction), DeviceAction,
        ""
    )
| where isnotempty(ClientIP) and isnotempty(RequestURL)
// Project the most relevant fields for analysis.
| project
    Timestamp,
    ClientIP,
    RequestURL,
    HttpResponseCode,
    Action,
    RuleName,
    MatchedError,
    TableName

// Source: https://github.com/pluralsight-cloud/azure-automated-incident-response
// Collected: 2026-05-17
// KQL Library - https://github.com/sivolko/kql-library

let lookback = 7d;
let port_opening = 
    AzureActivity
    | where TimeGenerated >= ago(lookback)
    | where OperationNameValue has_any ("ipfilterrules", "securityRules", "publicIPAddresses", "firewallrules")
          and OperationNameValue endswith "write"
    | where ActivityStatusValue has_any("Accepted", "Accept")
    | extend parsed_properties = parse_json(tostring(parse_json(Properties).responseBody)).properties
    | extend segs = split(_ResourceId, "/")
    | extend NSGRuleId = strcat_array(array_slice(segs, 0, array_length(segs)-3), "/")
    | extend destinationPortRange = case(Properties has_cs 'destinationPortRange', tostring(parsed_properties.destinationPortRange), "")
    | extend Name = tostring(split(Caller,'@',0)[0]), UPNSuffix = tostring(split(Caller,'@',1)[0])
    | project TimeGenerated, destinationPortRange, IPAddress = CallerIpAddress, Operation = OperationNameValue, NSGRuleId, Name, ETypeId='IMPROPER_PORT';
// Get NICs associated with NSGs
port_opening
| join kind=leftouter (
    arg("").Resources
    | where type == "microsoft.network/networkinterfaces"
    | extend attachedNSG = tostring(properties.networkSecurityGroup.id)
    | project nic_id = id, attachedNSG
) on $left.NSGRuleId == $right.attachedNSG
// Join NICs to their corresponding resource
| join kind=leftouter (
    arg("").Resources
    | mv-expand nics=properties.networkProfile.networkInterfaces
    | extend vm_id = id, nic_ref = tostring(nics.id)
    | project vm_id, nic_ref
) on $left.nic_id == $right.nic_ref
| project TimeGenerated, destinationPortRange, IPAddress, Operation, NSGRuleId, Name, VMResourceId=vm_id, ETypeId

